B.edC=new A.d4("q7",B.c6,"","You pierce my soul. I am half agony, half hope.","Jane Austen, Persuasion (1817)",B.Yz)
B.Yu=s(["kind"],t.s)
B.ed1=new A.d4("q8",B.c6,"","There is no charm equal to tenderness of heart.","Jane Austen, Emma (1815)",B.Yu)
B.qN=s(["close"],t.s)
B.edR=new A.d4("q9",B.c6,"","Whatever our souls are made of, his and mine are the same.","Emily Bront\xeb, Wuthering Heights (1847)",B.qN)
B.ed9=new A.d4("q10",B.c6,"","You are part of my existence, part of myself.","Charles Dickens, Great Expectations (1861)",B.qN)
B.ed4=new A.d4("q11",B.c6,"","What greater thing is there for two human souls, than to feel that they are joined for life\u2014to strengthen each other in all labour, to rest on each other in all sorrow, to minister to each other in all pain\u2026","George Eliot, Adam Bede (1859)",B.yd)
B.yc=s(["space"],t.s)
B.edH=new A.d4("q12",B.c6,"","Love one another, but make not a bond of love:\nLet it rather be a moving sea between the shores of your souls.","Kahlil Gibran, The Prophet (1923)",B.yc)
B.edv=new A.d4("q13",B.c6,"","And stand together yet not too near together:\nFor the pillars of the temple stand apart,\nAnd the oak tree and the cypress grow not in each other\u2019s shadow.","Kahlil Gibran, The Prophet (1923)",B.yc)
B.ecZ=new A.d4("q14",B.c6,"","Love gives naught but itself and takes naught but from itself.\nLove possesses not nor would it be possessed;\nFor love is sufficient unto love.","Kahlil Gibran, The Prophet (1923)",B.Cg)
B.edk=new A.d4("q15",B.c6,"","Many waters cannot quench love, neither can the floods drown it.","Song of Solomon 8:7, King James Bible (1611)",B.yd)
B.ed2=new A.d4("q16",B.c6,"","Set me as a seal upon thine heart.","Song of Solomon 8:6, King James Bible (1611)",B.qN)
B.edh=new A.d4("q17",B.c6,"","O my Luve is like a red, red rose\nThat\u2019s newly sprung in June.","Robert Burns, A Red, Red Rose (1794)",B.C8)
B.ezz=s(["admire","calm"],t.s)
B.edO=new A.d4("q18",B.c6,"","She walks in beauty, like the night\nOf cloudless climes and starry skies.","Lord Byron, She Walks in Beauty (1815)",B.ezz)
B.edA=new A.d4("q19",B.c6,"","The only way to have a friend is to be one.","Ralph Waldo Emerson, Friendship (1841)",B.Yu)
B.edN=new A.d4("q20",B.c6,"","Happy families are all alike; every unhappy family is unhappy in its own way.","Leo Tolstoy, Anna Karenina (1878; tr. Constance Garnett, 1901)",B.mk)
B.ecY=new A.d4("q21",B.c6,"","Love is like a cough \u2014 it cannot be hidden.\n(Mapenzi ni kikohozi, hayafichiki.)","Swahili proverb",B.C8)
